@dataclass(frozen=True, slots=True)
class LeaseRecoveryCircuitTrip:
    """One job durably parked by the unchanged-recovery containment."""

    job_id: str
    project_id: str | None
    unchanged_recoveries: int
    officer_destination: str
    officer_thread_id: str | None
    notification_queued: bool


@dataclass(frozen=True, slots=True)
class RecoveredJob:
    """One job a recovery sweep returned to the dispatchable pool.

    ``project_id`` is carried so fleet officer wakes can be scoped to the
    owning project's officer instead of broadcast to every officer; ``None``
    when the job belongs to no project.
    """

    job_id: str
    project_id: str | None = None


@dataclass(frozen=True, slots=True)
class LeaseRecoveryBatch:
    """Structured lease sweep result: only recovered ids may be dispatched."""

    recovered_jobs: tuple[RecoveredJob, ...] = ()
    circuit_trips: tuple[LeaseRecoveryCircuitTrip, ...] = ()

    @property
    def recovered_job_ids(self) -> tuple[str, ...]:
        return tuple(job.job_id for job in self.recovered_jobs)

    @property
    def changed(self) -> bool:
        return bool(self.recovered_jobs or self.circuit_trips)


@dataclass(frozen=True, slots=True)
class OrphanRecoveryBatch:
    """Agents-table orphan sweep result.

    ``count`` preserves the historical row-update total across all four
    mutation arms (a job touched by two arms counts twice, as it always has);
    ``recovered_jobs`` lists each distinct affected job once with its owning
    project, so officer capacity wakes can be scoped per project.
    """

    count: int = 0
    recovered_jobs: tuple[RecoveredJob, ...] = ()

    def __bool__(self) -> bool:
        return bool(self.count)


#: Every lifecycle status a job row may carry. Mirrors the cockpit's
#: ``JobStatus`` union; the jobs list validates ``?status=`` against it and
#: 422s on anything else, because silently returning zero rows for a typo
#: produces bug reports that read as data loss.
KNOWN_JOB_STATUSES: tuple[str, ...] = (
    "created",
    "pending",
    "processing",
    "completed",
    "failed",
    "cancelled",
    "pending_review",
    "paused",
    "reviewing",
    "waiting",
)
JOB_STATUS_FILTER_VALUES: tuple[str, ...] = (
    *KNOWN_JOB_STATUSES,
    "blocked_undelivered",
)

#: Where a job came from. Stamped explicitly by every caller of
#: :meth:`PostgresDB.create_job` — never inferred at write time, because the
#: caller always knows and a guess is how unattended work gets mislabelled as
#: human work. There is deliberately no CHECK constraint (0118's precedent on
#: this same hot table); validation lives here so a typo fails loudly in tests
#: and a new value costs no migration.
#:
#: ``lifecycle`` currently has no owner: scholar and critic children pass
#: ``runner_kind='lifecycle'``, but that column is the dispatch grant class,
#: not a provenance record, so those rows are ``subjob``. The value is
#: reserved for a real system-lifecycle creator.
KNOWN_JOB_ORIGINS: frozenset[str] = frozenset(
    {
        "user",
        "session",
        "automation",
        "loop",
        "officer",
        "subjob",
        "lifecycle",
        "bench",
    }
)

#: Ceiling for the filtered job count. An exact ``COUNT(*)`` over a filtered
#: set costs more than all the paging it accompanies and cannot be made cheap
#: — MVCC means there is no stored row count — so the count is computed inside
#: a ``LIMIT`` and reported as "N+" once it reaches this. GitLab caps at 1000
#: for the same reason; Stripe and Azure decline to return a total at all.
JOB_COUNT_CAP = 10_000


@dataclass(frozen=True, slots=True)
class JobQueryResult:
    """One page of jobs plus the counts a paging UI needs.

    ``total`` is a *capped* exact count: ``None`` when the caller opted out
    via ``include_total=False``, and paired with ``total_is_capped=True`` when
    the real total reached :data:`JOB_COUNT_CAP`. ``has_more`` is exact in
    every case, because it comes from fetching one row past the page rather
    than from comparing against ``total``.
    """

    jobs: list[dict[str, Any]]
    total: int | None = None
    total_is_capped: bool = False
    has_more: bool = False


def _completion_sweep_exclusion_clause(
    enabled: bool, *, job_alias: str = "jobs"
) -> str:
    """Return the shared Gate-3 rescue-ownership predicate when enabled.

    The disabled arm is the empty string on purpose: callers using the legacy
    path must not even parse or plan a reference to the rollout-only view.
    Restrict aliases to the two literal spellings used below so this helper
    never becomes an identifier-formatting surface.
    """

    if not enabled:
        return ""
    if job_alias not in {"jobs", "j"}:
        raise ValueError("unsupported jobs alias for completion sweep exclusion")
    return (
        " AND NOT EXISTS ("
        "SELECT 1 FROM job_completion_sweep_exclusions AS completion_route "
        f"WHERE completion_route.job_id = {job_alias}.id"
        ")"
    )


def _completion_control_active_sql(context_expression: str) -> str:
    """SQL predicate for a live or malformed control marker.

    A JSON number avoids any fallible text-to-timestamp cast (and works on the
    production PostgreSQL 15 cluster). Unknown/malformed marker shapes stay
    fail-closed.
    """

    marker = f"({context_expression})->'_completion_control_claim'"
    expiry = f"{marker}->'expires_epoch'"
    return (
        "CASE "
        f"WHEN NOT (COALESCE({context_expression}, '{{}}'::jsonb) "
        "? '_completion_control_claim') THEN false "
        f"WHEN jsonb_typeof({marker}) IS DISTINCT FROM 'object' THEN true "
        f"WHEN {marker}->>'version' IS DISTINCT FROM '1' THEN true "
        f"WHEN jsonb_typeof({expiry}) IS DISTINCT FROM 'number' THEN true "
        f"ELSE ({expiry}#>>'{{}}')::numeric "
        "> extract(epoch FROM clock_timestamp()) END"
    )


def _completion_control_owned_active_sql(
    context_expression: str,
    claim_parameter: str,
) -> str:
    """Strict exact-owner predicate for a still-live control marker."""

    marker = f"({context_expression})->'_completion_control_claim'"
    expiry = f"{marker}->'expires_epoch'"
    return (
        f"jsonb_typeof({marker}) = 'object' "
        f"AND {marker}->>'version' = '1' "
        f"AND {marker}->>'claim_id' = {claim_parameter}::text "
        f"AND jsonb_typeof({expiry}) = 'number' "
        f"AND ({expiry}#>>'{{}}')::numeric "
        "> extract(epoch FROM clock_timestamp())"
    )


def _completion_delivery_control_owned_active_sql(
    context_expression: str,
    claim_parameter: str,
) -> str:
    """Exact active command-owned delivery barrier consumed by S17."""

    marker = f"({context_expression})->'_completion_control_claim'"
    return (
        f"({_completion_control_owned_active_sql(context_expression, claim_parameter)}) "
        f"AND {marker}->>'source' = 'completion_delivery' "
        f"AND {marker}->>'fence_kind' = 'completion_command' "
        f"AND {marker}->>'fence_value' = {claim_parameter}::text"
    )


@dataclass(frozen=True, slots=True)
class _TaskTransactionScope:
    """One connection reusable only by the task that opened its transaction.

    ``ContextVar`` values are copied into child tasks.  Keeping the owning task
    alongside the connection is therefore essential: a fire-and-forget task
    created inside a transaction must acquire its own connection instead of
    inheriting one that may commit or return to the pool before the child runs.
    """

    database: "PostgresDB"
    connection: Any
    owner_task: asyncio.Task[Any]


_TASK_TRANSACTION_SCOPE: ContextVar[_TaskTransactionScope | None] = ContextVar(
    "postgres_task_transaction_scope", default=None
)


def _strict_json_object(value: Any, *, label: str) -> dict[str, Any]:
    """Return one JSON object without treating malformed falsey values as empty."""

    if isinstance(value, dict):
        return dict(value)
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except (TypeError, ValueError) as exc:
            raise RuntimeError(f"{label} is malformed") from exc
        if isinstance(parsed, dict):
            return dict(parsed)
    raise RuntimeError(f"{label} is malformed")


def _json_object_or_empty(value: Any) -> dict[str, Any]:
    """Tolerant JSONB object decode for recovery/diagnostic read paths."""

    if isinstance(value, Mapping):
        return dict(value)
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except (TypeError, ValueError):
            return {}
        return dict(parsed) if isinstance(parsed, Mapping) else {}
    return {}


def _nonnegative_int(value: Any) -> int:
    """Best-effort integer for server-owned recovery diagnostics."""

    try:
        return max(0, int(value or 0))
    except (TypeError, ValueError, OverflowError):
        return 0


def _canonical_uuid_text(value: Any, *, label: str) -> str:
    if isinstance(value, bool) or not isinstance(value, str):
        raise RuntimeError(f"{label} is malformed")
    try:
        parsed = UUID(value)
    except (TypeError, ValueError) as exc:
        raise RuntimeError(f"{label} is malformed") from exc
    canonical = str(parsed)
    if value != canonical:
        raise RuntimeError(f"{label} is malformed")
    return canonical


def _stateless_runtime_creation_marker(
    workspace: dict[str, Any],
) -> dict[str, Any] | None:
    """Strictly parse one durable, one-shot Kubernetes create authority."""

    if _STATELESS_RUNTIME_CREATION_KEY not in workspace:
        return None
    raw = workspace[_STATELESS_RUNTIME_CREATION_KEY]
    if not isinstance(raw, dict) or set(raw) != _STATELESS_RUNTIME_CREATION_FIELDS:
        raise RuntimeError("stateless runtime creation marker is malformed")
    marker = dict(raw)
    generation = _canonical_uuid_text(
        marker.get("generation"), label="stateless runtime creation generation"
    )
    mode = marker.get("mode")
    if mode not in {"create", "restore"}:
        raise RuntimeError("stateless runtime creation mode is malformed")
    attempted = marker.get("attempted")
    if type(attempted) is not bool:
        raise RuntimeError("stateless runtime creation attempted flag is malformed")
    replaces_uid = marker.get("replaces_uid")
    if replaces_uid is not None:
        replaces_uid = _canonical_uuid_text(
            replaces_uid,
            label="stateless runtime creation replacement incarnation",
        )
    return {
        "generation": generation,
        "mode": mode,
        "attempted": attempted,
        "replaces_uid": replaces_uid,
    }


def _stateless_runtime_creation_context(
    row: Any,
) -> tuple[dict[str, Any], dict[str, Any], str | None, dict[str, Any] | None]:
    """Validate the thread authority shared by every creation transition."""

    if str(row.get("execution_lane") or "") != "stateless":
        raise RuntimeError("thread is not stateless")
    if str(row.get("status") or "") not in {"created", "active", "awaiting_user"}:
        raise RuntimeError("thread lifecycle does not permit workspace creation")
    metadata = _strict_json_object(row.get("metadata"), label="thread metadata")
    for key in (
        "_stateless_workspace_retirement_pending",
        "_stateless_claim_retirement",
        "_stateless_claim_loss_hold",
        "_stateless_claim_losses",
    ):
        if key in metadata:
            raise RuntimeError("thread lifecycle does not permit workspace creation")
    if "protected_cloud" in metadata and metadata["protected_cloud"] is not False:
        raise RuntimeError("protected cloud sessions require the pinned lane")
    raw_workspace = metadata.get("workspace_container", {})
    if not isinstance(raw_workspace, dict):
        raise RuntimeError("thread workspace metadata is malformed")
    workspace = dict(raw_workspace)
    if workspace.get("provisioner") != "k8s":
        raise RuntimeError("stateless workspace is not Kubernetes-backed")
    restore_value = workspace.get("_snapshot_restore_required", False)
    if "_snapshot_restore_required" in workspace and type(restore_value) is not bool:
        raise RuntimeError("snapshot restore marker is malformed")
    runtime = workspace.get(_STATELESS_RUNTIME_INCARNATION_KEY)
    if runtime is not None:
        runtime = _canonical_uuid_text(
            runtime, label="stateless workspace runtime incarnation"
        )
    marker = _stateless_runtime_creation_marker(workspace)
    if marker is not None and (restore_value is True) is not (
        marker["mode"] == "restore"
    ):
        raise RuntimeError("workspace create marker disagrees with restore intent")
    return metadata, workspace, runtime, marker


def _thread_datasource_lock_key(thread_id: str) -> int:
    """Stable, domain-separated advisory-lock key for connector delivery.

    Connector selection writes and credential delivery must use the same lock
    domain.  Keeping it separate from the general thread provisioning lock
    also makes it safe to attach while provisioning already owns that lock.
    """
    digest = hashlib.blake2b(
        b"datasource_selection:" + thread_id.encode(), digest_size=8
    ).digest()
    return int.from_bytes(digest, byteorder="big", signed=True)


def _stateless_cancel_cleanup_lock_key(job_id: UUID) -> int:
    """Domain-separated session advisory key for one cancel cleanup owner."""
    digest = hashlib.blake2b(
        b"stateless_cancel_cleanup:" + job_id.bytes,
        digest_size=8,
    ).digest()
    return int.from_bytes(digest, byteorder="big", signed=True)


def _stateless_session_workspace_ensure_lock_key(thread_id: str) -> int:
    """Domain-separated session advisory key for physical workspace recovery."""
    try:
        identity = UUID(str(thread_id)).bytes
    except (TypeError, ValueError):
        # Non-UUID ids exist only in isolated tests/legacy fixtures. Preserve a
        # stable fallback while canonicalizing every production thread UUID so
        # upper/lower/text spellings cannot split one lifecycle lock.
        identity = str(thread_id).strip().lower().encode()
    digest = hashlib.blake2b(
        b"stateless_session_workspace_ensure:" + identity,
        digest_size=8,
    ).digest()
    return int.from_bytes(digest, byteorder="big", signed=True)


class DatasourcePolicyError(ValueError):
    """Base class for datasource scope/default persistence failures."""


class DatasourcePolicyValidationError(DatasourcePolicyError):
    """A requested datasource policy is structurally invalid."""


class DatasourcePolicyConflictError(DatasourcePolicyError):
    """The caller edited a stale datasource policy revision."""


class DatasourceProjectAuthorizationError(DatasourcePolicyError):
    """A project-link addition lost its required owner authority."""


class DatasourceScopeAuthorizationError(DatasourcePolicyError):
    """A project-scoped principal attempted a cross-scope datasource mutation."""


class DatasourceMaterializationAuthorizationError(DatasourcePolicyError):
    """A work owner lost approval or target-project access before insert."""


class DatasourceCatalogCursorError(ValueError):
    """A datasource catalog/linkable-project cursor is malformed."""


class OfficerPostLifecycleConflict(RuntimeError):
    """A stale/invalid Officer Post lifecycle mutation lost its CAS."""

    def __init__(self, code: str, detail: str):
        super().__init__(detail)
        self.code = code
        self.detail = detail


def _uuid_list(values: list[str] | tuple[str, ...] | None) -> list[UUID]:
    """Parse and de-duplicate UUID strings while preserving request order.

    Database write APIs use this only after the request layer has decided
    whether a field was omitted. Malformed UUIDs are rejected rather than
    silently dropped so an atomic attachment or scope edit cannot commit a
    partial data contract.
    """
    result: list[UUID] = []
    seen: set[UUID] = set()
    for value in values or ():
        try:
            parsed = UUID(str(value))
        except (TypeError, ValueError) as exc:
            raise DatasourcePolicyValidationError(
                "One or more connector or project identifiers are invalid"
            ) from exc
        if parsed not in seen:
            seen.add(parsed)
            result.append(parsed)
    return result


def _stateless_resume_context(
    context_merge: Dict[str, Any] | None,
) -> Dict[str, Any]:
    """Attach durable per-resume identities to one-shot worker inputs."""

    merged = dict(context_merge or {})
    merged["worker_resume_id"] = str(uuid4())
    if merged.get("queued_feedback") is not None:
        merged.setdefault("queued_feedback_reason", None)
        merged["queued_feedback_delivery_id"] = str(uuid4())
    if merged.get("delegation_results") is not None:
        merged["delegation_results_delivery_id"] = str(uuid4())
    return merged


@asynccontextmanager
async def _transaction_if(conn, enabled: bool):
    """Open an asyncpg transaction only for multi-statement operations.

    Single INSERT/UPDATE operations are already atomic. Avoiding a redundant
    transaction also preserves the lightweight mocked-connection contract used
    throughout the database unit tests.
    """
    if enabled:
        async with conn.transaction():
            yield
    else:
        yield


async def _require_project_owner_for_link_additions(
    conn,
    project_uuids: list[UUID],
    *,
    authority_user_id: str | None,
    authority_is_admin: bool,
) -> bool | None:
    """Lock and re-check project-owner authority for new connector links.

    HTTP handlers perform the same check before entering persistence so they
    can return useful project-specific errors. This in-transaction check is
    the security boundary: locking the matching membership rows prevents a
    concurrent role downgrade/removal from committing until the link write has
    either committed or rolled back. Server-managed provisioning may omit an
    authority identity; an authenticated admin explicitly bypasses the role
    lookup.
    """
    if not project_uuids or authority_user_id is None:
        return None
    try:
        authority_uuid = UUID(str(authority_user_id))
    except (TypeError, ValueError) as exc:
        raise DatasourceProjectAuthorizationError(
            "Project owner role required for connector link additions"
        ) from exc

    actor = await conn.fetchrow(
        """
        SELECT is_admin, is_approved
        FROM users
        WHERE id = $1
        FOR UPDATE
        """,
        authority_uuid,
    )
    if actor is None or not bool(actor["is_approved"]):
        raise DatasourceProjectAuthorizationError(
            "Project owner role required for connector link additions"
        )
    if bool(actor["is_admin"]):
        return True

    rows = await conn.fetch(
        """
        SELECT project_id
        FROM project_members
        WHERE user_id = $1
          AND project_id = ANY($2::uuid[])
          AND role = 'owner'
        ORDER BY project_id
        FOR UPDATE
        """,
        authority_uuid,
        project_uuids,
    )
    authorized = {row["project_id"] for row in rows}
    if authorized != set(project_uuids):
        raise DatasourceProjectAuthorizationError(
            "Project owner role required for connector link additions"
        )
    return False


async def _require_project_link_mutation_authority(
    conn,
    project_uuid: UUID,
    *,
    datasource_created_by: UUID | None,
    authority_user_id: str | None,
    authority_is_admin: bool,
    allow_connector_owner: bool,
) -> None:
    """Lock and re-check authority immediately before a link mutation.

    The request-layer owner check provides an early, useful denial, but this
    transaction-local check is the authorization boundary. The caller's admin
    hint is deliberately not trusted: the current user row and, when needed,
    current project-owner membership are locked before the child row changes.
    Connector creators retain the established right to revoke their own link.
    Trusted internal lifecycle callers may omit ``authority_user_id``.
    """
    del authority_is_admin
    if authority_user_id is None:
        return
    try:
        authority_uuid = UUID(str(authority_user_id))
    except (TypeError, ValueError) as exc:
        raise DatasourceProjectAuthorizationError(
            "Project owner role required for connector link mutation"
        ) from exc

    actor = await conn.fetchrow(
        """
        SELECT is_admin, is_approved
        FROM users
        WHERE id = $1
        FOR UPDATE
        """,
        authority_uuid,
    )
    if actor is None or not bool(actor["is_approved"]):
        raise DatasourceProjectAuthorizationError(
            "Project owner role required for connector link mutation"
        )
    if bool(actor["is_admin"]):
        return
    if allow_connector_owner and str(datasource_created_by or "") == str(
        authority_uuid
    ):
        return

    membership = await conn.fetchrow(
        """
        SELECT project_id
        FROM project_members
        WHERE user_id = $1
          AND project_id = $2
          AND role = 'owner'
        FOR UPDATE
        """,
        authority_uuid,
        project_uuid,
    )
    if membership is None:
        raise DatasourceProjectAuthorizationError(
            "Project owner role required for connector link mutation"
        )


async def _lock_and_validate_work_owner(
    conn,
    *,
    authority_user_id: str | None,
    materialized_user_uuid: UUID | None,
    target_project_uuids: list[UUID],
) -> None:
    """Lock and re-check the effective owner at work materialization.

    Datasource selection happens before the job/thread transaction. Locking the
    current user and membership rows in the same transaction as the work insert
    closes the interval in which an owner could be disabled or removed from a
    target project after policy resolution but before credentials are bound to
    durable work. Trusted ownerless system work opts out explicitly by omitting
    ``authority_user_id``.
    """
    if authority_user_id is None:
        return
    try:
        authority_uuid = UUID(str(authority_user_id))
    except (TypeError, ValueError) as exc:
        raise DatasourceMaterializationAuthorizationError(
            "Work owner is no longer authorized"
        ) from exc
    if materialized_user_uuid is None or authority_uuid != materialized_user_uuid:
        raise DatasourceMaterializationAuthorizationError(
            "Work owner is no longer authorized"
        )

    actor = await conn.fetchrow(
        """
        SELECT is_admin, is_approved
        FROM users
        WHERE id = $1
        FOR UPDATE
        """,
        authority_uuid,
    )
    if actor is None or not bool(actor["is_approved"]):
        raise DatasourceMaterializationAuthorizationError(
            "Work owner is no longer authorized"
        )
    if bool(actor["is_admin"]) or not target_project_uuids:
        return

    rows = await conn.fetch(
        """
        SELECT project_id
        FROM project_members
        WHERE user_id = $1
          AND project_id = ANY($2::uuid[])
        ORDER BY project_id
        FOR UPDATE
        """,
        authority_uuid,
        target_project_uuids,
    )
    if {row["project_id"] for row in rows} != set(target_project_uuids):
        raise DatasourceMaterializationAuthorizationError(
            "Work owner is no longer authorized"
        )


def _encode_page_cursor(payload: Dict[str, Any]) -> str:
    raw = json.dumps(payload, separators=(",", ":"), default=str).encode()
    return base64.urlsafe_b64encode(raw).decode().rstrip("=")


def _decode_page_cursor(cursor: str | None) -> Dict[str, Any] | None:
    if not cursor:
        return None
    try:
        padding = "=" * (-len(cursor) % 4)
        decoded = base64.urlsafe_b64decode((cursor + padding).encode())
        value = json.loads(decoded)
    except Exception as exc:
        raise DatasourceCatalogCursorError("Invalid pagination cursor") from exc
    if not isinstance(value, dict):
        raise DatasourceCatalogCursorError("Invalid pagination cursor")
    return value


def _normalize_policy_revision_snapshot(
    datasource_uuids: list[UUID],
    supplied: Dict[str, int] | None,
    provenance: Dict[str, Any] | None,
) -> Dict[UUID, int]:
    """Normalize the policy snapshot required for nonempty materialization."""
    raw = supplied
    if raw is None and provenance is not None:
        candidate = provenance.get("policy_revisions")
        if isinstance(candidate, dict):
            raw = candidate
    if not datasource_uuids:
        if raw not in (None, {}):
            raise DatasourcePolicyValidationError(
                "The connector policy revision snapshot must match the complete selection"
            )
        return {}
    if raw is None:
        raise DatasourcePolicyValidationError(
            "A connector policy revision snapshot is required"
        )
    normalized: Dict[UUID, int] = {}
    try:
        for datasource_id, revision in raw.items():
            parsed_id = UUID(str(datasource_id))
            parsed_revision = int(revision)
            if parsed_revision < 1:
                raise ValueError
            normalized[parsed_id] = parsed_revision
    except (AttributeError, TypeError, ValueError) as exc:
        raise DatasourcePolicyValidationError(
            "The connector policy revision snapshot is invalid"
        ) from exc
    if set(normalized) != set(datasource_uuids):
        raise DatasourcePolicyValidationError(
            "The connector policy revision snapshot must match the complete selection"
        )
    return normalized


async def _lock_and_compare_policy_snapshot(
    conn,
    datasource_uuids: list[UUID],
    expected_revisions: Dict[UUID, int],
    *,
    legacy_job_id: UUID | None = None,
) -> None:
    """Lock the selected policy rows through work+attachment commit."""
    if not datasource_uuids:
        return
    rows = await conn.fetch(
        """
        SELECT id, policy_revision
        FROM datasources
        WHERE id = ANY($1::uuid[])
          AND (job_id IS NULL OR job_id = $2::uuid)
        ORDER BY id
        FOR UPDATE
        """,
        sorted(datasource_uuids, key=str),
        legacy_job_id,
    )
    current = {row["id"]: int(row["policy_revision"]) for row in rows}
    if current != expected_revisions:
        raise DatasourcePolicyConflictError(
            "Connector policy changed; resolve the selection and try again"
        )


def _encrypt_optional(value: str | None) -> str | None:
    """Encrypt a credential before storage. NULL stays NULL; empty is treated as NULL."""
    if value is None or value == "":
        return None
    return encrypt(value)


def _decrypt_stored(value: str | None, *, field: str) -> str | None:
    """Decrypt a credential after fetch. NULL stays NULL.

    If the value is not a v1 ciphertext (e.g. pre-encryption dev data), the
    row is unusable — return None and log rather than crash the caller. Pre-
    production upgrade path: operators re-add keys through the UI.
    """
    if value is None:
        return None
    if not is_encrypted(value):
        logger.warning(
            "Encountered non-encrypted value in %s; ignoring. "
            "Re-add the credential via the UI.",
            field,
        )
        return None
    try:
        return decrypt(value)
    except DecryptionError as exc:
        logger.error("Failed to decrypt %s: %s", field, exc)
        return None


def _encrypt_credentials_dict(creds: Dict[str, Any] | None) -> str:
    """Encrypt a credentials dict for insertion into a JSONB column.

    Returns a JSON string ready to pass as a JSONB parameter. Empty/None
    becomes JSONB ``'{}'`` (no encryption needed — empty has no secret to
    protect, and the schema default is ``'{}'``).

    A non-empty dict is JSON-serialized, encrypted with :func:`encrypt`,
    then wrapped again with :func:`json.dumps` so the JSONB column receives
    a valid JSON string value (e.g. ``"v1:<nonce>:<ct>"``).
    """
    if not creds:
        return "{}"
    return json.dumps(encrypt(json.dumps(creds)))


def _decrypt_credentials_field(
    raw: Any, *, field: str = "datasources.credentials"
) -> Dict[str, Any]:
    """Decrypt a credentials JSONB value, returning the plaintext dict.

    asyncpg returns JSONB as a raw JSON string here (no codec registered).
    This helper parses the JSON and handles three cases:

    1. **Legacy plaintext** — JSON object (pre-encryption rows). Returned
       as-is with a warning so operators can re-save to upgrade.
    2. **Encrypted** — JSON string with ``v1:`` prefix. Decrypted and
       JSON-parsed back into a dict.
    3. **Other / malformed** — empty dict, logged.

    Always returns a dict (possibly empty) so callers never have to handle
    None, string, or dict variants.
    """
    if raw is None:
        return {}

    if isinstance(raw, str):
        try:
            parsed: Any = json.loads(raw)
        except (json.JSONDecodeError, ValueError) as exc:
            logger.error("Failed to parse %s JSON: %s", field, exc)
            return {}
    else:
        parsed = raw  # asyncpg with a JSON codec would land here

    if isinstance(parsed, dict):
        if parsed:
            logger.warning(
                "Legacy plaintext credentials in %s; re-save the datasource to encrypt.",
                field,
            )
        return parsed

    if isinstance(parsed, str):
        if not is_encrypted(parsed):
            logger.warning(
                "Non-encrypted credential string in %s; treating as empty.", field
            )
            return {}
        try:
            plaintext = decrypt(parsed)
            return json.loads(plaintext)
        except (DecryptionError, json.JSONDecodeError, ValueError) as exc:
            logger.error("Failed to decrypt %s: %s", field, exc)
            return {}

    logger.warning(
        "Unexpected credentials type %s in %s; treating as empty.",
        type(parsed).__name__,
        field,
    )
    return {}


def _datasource_row_to_dict(
    row, *, field: str = "datasources.credentials"
) -> Dict[str, Any]:
    """Convert a datasource asyncpg Record to a dict with decrypted credentials.

    Use anywhere a SELECT returns a datasource row. The ``credentials`` field
    is replaced with its decrypted plaintext dict (always a dict, never the
    raw JSONB string).
    """
    d = dict(row)
    if "credentials" in d:
        d["credentials"] = _decrypt_credentials_field(d["credentials"], field=field)
    if "config" in d:
        raw_config = d["config"]
        if isinstance(raw_config, str):
            try:
                raw_config = json.loads(raw_config)
            except (json.JSONDecodeError, ValueError) as exc:
                logger.error("Failed to parse datasources.config JSON: %s", exc)
                raw_config = {}
        if raw_config is None:
            raw_config = {}
        if not isinstance(raw_config, dict):
            logger.warning(
                "Unexpected datasources.config type %s; treating as empty.",
                type(raw_config).__name__,
            )
            raw_config = {}
        d["config"] = raw_config
    return d


